import { useState, useEffect, useRef } from 'react';
import { formatTime } from '../../utils/helpers';

const ExamInterface = ({ exam, questions, store, onFinish }) => {
  const [currentQ,      setCurrentQ]      = useState(0);
  const [answers,       setAnswers]       = useState({});
  const [timeLeft,      setTimeLeft]      = useState(exam.duration_minutes * 60);
  const [submitting,    setSubmitting]    = useState(false);
  const [confirmSubmit, setConfirmSubmit] = useState(false);

  // ── Anti-cheat state ──────────────────────────────────────
  const [tabViolations,  setTabViolations]  = useState(0);
  const [showWarning,    setShowWarning]    = useState(false);   // first warning modal
  const [terminated,     setTerminated]     = useState(false);   // auto-submit triggered
  const MAX_VIOLATIONS = 1; // one strike and exam ends

  const timerRef    = useRef();
  const subRef      = useRef();
  const warnTimeout = useRef();

  useEffect(() => {
    const init = async () => {
      const sub = await store.startSubmission(exam.exam_id);
      subRef.current = sub;
    };
    init();
  }, []);

  // Timer
  useEffect(() => {
    timerRef.current = setInterval(() => {
      setTimeLeft(t => {
        if (t <= 1) { clearInterval(timerRef.current); handleSubmit(true, false); return 0; }
        return t - 1;
      });
    }, 1000);
    return () => clearInterval(timerRef.current);
  }, []);

  // ── TAB SWITCH DETECTION ─────────────────────────────────
  useEffect(() => {
    const onVisibilityChange = () => {
      if (document.hidden && !terminated) {
        setTabViolations(v => {
          const next = v + 1;
          if (next > MAX_VIOLATIONS) {
            // Already terminated — do nothing
            return next;
          }
          if (next === MAX_VIOLATIONS) {
            // First violation: warn
            setShowWarning(true);
            store.addToast('⚠ Tab switch detected! One more will end your exam.', 'error');
            return next;
          }
          // Max violations hit — terminate
          return next;
        });
      }
    };

    const onBlur = () => {
      if (!terminated) {
        setTabViolations(v => {
          const next = v + 1;
          if (next > MAX_VIOLATIONS) return next;
          if (next <= MAX_VIOLATIONS) {
            setShowWarning(true);
            store.addToast('⚠ Tab switch detected!', 'error');
          }
          return next;
        });
      }
    };

    document.addEventListener('visibilitychange', onVisibilityChange);
    window.addEventListener('blur', onBlur);
    return () => {
      document.removeEventListener('visibilitychange', onVisibilityChange);
      window.removeEventListener('blur', onBlur);
    };
  }, [terminated]);

  // When violations exceed max → auto-terminate
  useEffect(() => {
    if (tabViolations > MAX_VIOLATIONS && !terminated) {
      setTerminated(true);
      setShowWarning(false);
      handleCheatSubmit();
    }
  }, [tabViolations]);

  // ── Submit with score 0 due to cheating ──────────────────
  const handleCheatSubmit = async () => {
    if (!subRef.current) return;
    clearInterval(timerRef.current);
    setSubmitting(true);
    // Submit with empty answers (so score = 0) and mark as cheated
    await store.submitExam(subRef.current.submission_id, {}, exam.exam_id, true);
    setSubmitting(false);
    onFinish(subRef.current.submission_id, true);
  };

  const handleSubmit = async (auto = false, cheated = false) => {
    if (!subRef.current) return;
    clearInterval(timerRef.current);
    setSubmitting(true);
    if (!auto) store.addToast('Submitting exam...', 'info');
    await store.submitExam(subRef.current.submission_id, answers, exam.exam_id, cheated);
    setSubmitting(false);
    onFinish(subRef.current.submission_id, cheated);
  };

  const dismissWarning = () => { setShowWarning(false); };

  const setAnswer     = (qid, val) => setAnswers(a => ({ ...a, [qid]: val }));
  const q             = questions[currentQ];
  const answeredCount = Object.keys(answers).length;
  const pct           = (timeLeft / (exam.duration_minutes * 60)) * 100;
  const timerClass    = timeLeft < 60 ? 'danger' : timeLeft < 300 ? 'warning' : '';

  return (
    <div>
      {/* Submitting overlay */}
      {submitting && (
        <div style={{ position:'fixed', inset:0, background:'rgba(15,15,26,0.75)', zIndex:2000, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:16 }}>
          <div style={{ width:44, height:44, borderRadius:'50%', border:'3px solid rgba(255,255,255,.2)', borderTop:'3px solid #7c3aed', animation:'spin .7s linear infinite' }}/>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:18, color:'#fff' }}>
            {terminated ? 'Exam terminated...' : 'Submitting your exam...'}
          </div>
          <div style={{ fontSize:13, color:'rgba(255,255,255,.6)' }}>Please wait while we save your answers</div>
        </div>
      )}

      {/* ── CHEATING WARNING MODAL ── */}
      {showWarning && (
        <div style={{ position:'fixed', inset:0, background:'rgba(0,0,0,.65)', zIndex:1999, display:'flex', alignItems:'center', justifyContent:'center', padding:20 }}>
          <div style={{ background:'#fff', borderRadius:16, padding:'28px 32px', maxWidth:460, width:'100%', border:'2px solid #fca5a5', boxShadow:'0 24px 60px rgba(0,0,0,.3)' }}>
            <div style={{ display:'flex', gap:14, alignItems:'flex-start', marginBottom:20 }}>
              <div style={{ width:48, height:48, borderRadius:12, background:'#fee2e2', display:'flex', alignItems:'center', justifyContent:'center', fontSize:24, flexShrink:0 }}>⚠</div>
              <div>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:18, color:'#dc2626', marginBottom:6 }}>Tab Switch Detected!</div>
                <div style={{ fontSize:13, color:'#374151', lineHeight:1.65 }}>
                  You switched away from this exam window. <strong>This is your only warning.</strong>
                </div>
              </div>
            </div>
            <div style={{ background:'#fef2f2', border:'1px solid #fecaca', borderRadius:10, padding:'12px 16px', marginBottom:20, fontSize:13, color:'#7f1d1d', lineHeight:1.65 }}>
              If you switch tabs or minimize this window again, your exam will be <strong>automatically terminated with a score of 0</strong>.
            </div>
            <div style={{ display:'flex', justifyContent:'center' }}>
              <button onClick={dismissWarning}
                style={{ padding:'10px 32px', background:'#dc2626', color:'#fff', border:'none', borderRadius:10, fontWeight:700, fontSize:14, cursor:'pointer' }}>
                I Understand — Return to Exam
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── TERMINATION OVERLAY ── */}
      {terminated && !submitting && (
        <div style={{ position:'fixed', inset:0, background:'rgba(127,29,29,.9)', zIndex:1998, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:16, padding:20 }}>
          <div style={{ fontSize:52, marginBottom:4 }}>🚫</div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:26, color:'#fff', textAlign:'center' }}>Exam Terminated</div>
          <div style={{ fontSize:15, color:'rgba(255,255,255,.8)', textAlign:'center', maxWidth:420, lineHeight:1.7 }}>
            Multiple tab switches were detected. Your exam has been automatically submitted with a score of 0.
          </div>
        </div>
      )}

      {/* ── ANTI-CHEAT STATUS BAR ── */}
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:10, padding:'8px 16px', marginBottom:16, display:'flex', alignItems:'center', gap:10 }}>
        <span style={{ fontSize:12, fontWeight:600, color:'#374151' }}>🔒 Exam Monitor Active</span>
        <div style={{ width:1, height:16, background:'#e5e7eb' }}/>
        <span style={{ fontSize:11, color:'#6b7280', fontFamily:'JetBrains Mono,monospace' }}>Tab switching is monitored</span>
        <div style={{ marginLeft:'auto', display:'flex', gap:6 }}>
          {[...Array(MAX_VIOLATIONS+1)].map((_,i) => (
            <div key={i} style={{ width:10, height:10, borderRadius:'50%', background:i < tabViolations ? '#dc2626' : '#e5e7eb', border:`1px solid ${i < tabViolations ? '#fca5a5' : '#d1d5db'}` }}/>
          ))}
          <span style={{ fontSize:10, color:tabViolations>0?'#dc2626':'#9ca3af', fontFamily:'JetBrains Mono,monospace', marginLeft:4, fontWeight:700 }}>
            {tabViolations === 0 ? 'Clean' : `${tabViolations} violation${tabViolations>1?'s':''}`}
          </span>
        </div>
      </div>

      {/* ── EXAM HEADER ── */}
      <div style={{ marginBottom:20, display:'flex', alignItems:'center', justifyContent:'space-between' }}>
        <div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:20, color:'#0f0f1a' }}>{exam.title}</div>
          <div style={{ fontSize:12, color:'#6b7280', marginTop:2 }}>Question {currentQ+1} of {questions.length} · {answeredCount} answered</div>
        </div>
        {confirmSubmit ? (
          <div style={{ display:'flex', gap:8, alignItems:'center', background:'#f3f4f6', padding:'6px 10px', borderRadius:9, border:'1px solid #e5e7eb' }}>
            <span style={{ fontSize:12, color:'#374151', fontWeight:600 }}>Submit exam?</span>
            <button className="btn btn-success btn-sm" onClick={() => handleSubmit(false, false)}>Yes, Submit</button>
            <button className="btn btn-ghost btn-sm" onClick={() => setConfirmSubmit(false)}>Cancel</button>
          </div>
        ) : (
          <button className="btn btn-primary" onClick={() => setConfirmSubmit(true)}>Submit Exam</button>
        )}
      </div>

      <div className="exam-layout">
        {/* Question panel */}
        <div className="exam-question-panel">
          <div className="question-counter">{q.question_type.replace('_',' ')} · {q.difficulty} · {q.marks} marks</div>
          <div className="question-text">{currentQ+1}. {q.question_text}</div>

          {q.question_type === 'MCQ' && (
            <div className="options-grid">
              {q.options?.map((opt, oi) => {
                const letter = ['A','B','C','D'][oi];
                return (
                  <div key={opt.option_id} className={`option-item ${answers[q.question_id]===letter?'selected':''}`} onClick={() => setAnswer(q.question_id, letter)}>
                    <div className="option-letter">{letter}</div>
                    <div className="option-text">{opt.text}</div>
                  </div>
                );
              })}
            </div>
          )}

          {q.question_type === 'TRUE_FALSE' && (
            <div className="tf-options">
              {['True','False'].map(v => (
                <div key={v} className={`tf-option ${v.toLowerCase()}-opt ${answers[q.question_id]===v?'selected':''}`} onClick={() => setAnswer(q.question_id, v)}>
                  {v==='True'?'✓ True':'✕ False'}
                </div>
              ))}
            </div>
          )}

          {(q.question_type==='SHORT_ANSWER'||q.question_type==='DESCRIPTIVE') && (
            <div style={{ marginBottom:24 }}>
              <textarea className="form-textarea"
                style={{ minHeight:q.question_type==='DESCRIPTIVE'?180:100, fontSize:14 }}
                value={answers[q.question_id]||''}
                onChange={e=>setAnswer(q.question_id,e.target.value)}
                placeholder={q.question_type==='DESCRIPTIVE'?'Write your detailed answer here...':'Write your answer here...'}/>
            </div>
          )}

          <div className="question-nav">
            <button className="btn btn-secondary" onClick={() => setCurrentQ(c=>Math.max(0,c-1))} disabled={currentQ===0}>← Previous</button>
            <button className="btn btn-secondary" onClick={() => setCurrentQ(c=>Math.min(questions.length-1,c+1))} disabled={currentQ===questions.length-1}>Next →</button>
          </div>
        </div>

        {/* Sidebar */}
        <div className="exam-sidebar-panel">
          <div className="timer-display">
            <div className="timer-label">Time Remaining</div>
            <div className={`timer-value ${timerClass}`}>{formatTime(timeLeft)}</div>
            <div className="progress-bar">
              <div className="progress-fill" style={{ width:`${pct}%`, background:timeLeft<60?'var(--danger)':timeLeft<300?'var(--warning)':undefined }}/>
            </div>
          </div>

          <div className="card" style={{ padding:16 }}>
            <div style={{ fontSize:11, color:'var(--text3)', textTransform:'uppercase', letterSpacing:'2px', marginBottom:10 }}>Questions</div>
            <div className="question-grid">
              {questions.map((qq,i) => (
                <div key={qq.question_id} className={`q-dot ${answers[qq.question_id]?'answered':''} ${i===currentQ?'current':''}`} onClick={() => setCurrentQ(i)}>{i+1}</div>
              ))}
            </div>
            <div style={{ marginTop:12, fontSize:11, color:'var(--text3)' }}>
              <span style={{ color:'var(--accent)' }}>■</span> Answered ({answeredCount}) &nbsp;
              <span style={{ color:'var(--border2)' }}>■</span> Unanswered ({questions.length-answeredCount})
            </div>
          </div>

          <div style={{ fontSize:12, color:'var(--text3)', background:'var(--surface2)', borderRadius:8, padding:12 }}>
            <div style={{ color:'var(--accent2)', fontSize:11, letterSpacing:2, marginBottom:4 }}>SCORING</div>
            MCQ / T-F: Auto-graded<br/>
            Short Answer: Keyword match<br/>
            Total: {exam.total_marks} marks
          </div>
        </div>
      </div>
    </div>
  );
};

export default ExamInterface;
